#!/usr/bin/env node
// Regenerates the browser data files in this directory for src/zh_converter.js.
//
//   node third_party/zh_js/generate_data.js <opencc-dictionaries-dir> <glyph-pack-dir>
//
// <opencc-dictionaries-dir> holds the OpenCC text dictionaries (STCharacters.txt,
// STPhrases.txt, TWVariants.txt, HKVariants.txt; Apache-2.0, as bundled with the
// ferrous-opencc 0.4 crate). <glyph-pack-dir> holds the FPG1/FPG2 glyph packs
// generated from SIL OFL 1.1 pixel fonts (cubic11.glyphs, latin_cubic11.glyphs,
// fusion12_zh_hk.glyphs, latin_fusion12.glyphs) by the MIT-licensed
// tamagotchi-paradise-zh-patcher glyphpack-gen tool.
//
// Only OFL / Apache-2.0 inputs are accepted. The Zpix pack is refused on purpose.
'use strict';
const fs = require('fs');
const path = require('path');

const [dictDir, glyphDir] = process.argv.slice(2);
if (!dictDir || !glyphDir) {
  console.error('usage: node generate_data.js <opencc-dictionaries-dir> <glyph-pack-dir>');
  process.exit(2);
}
const out = __dirname;

// GB2312 hanzi block used by the game's font: rows B0..F7, minus D7FA..D7FE.
function gb2312Hanzi() {
  const dec = new TextDecoder('gbk', { fatal: true });
  const set = new Set();
  for (let a = 0xB0; a <= 0xF7; a++) for (let b = 0xA1; b <= 0xFE; b++) {
    if (a === 0xD7 && b > 0xF9) continue;
    try { const s = dec.decode(new Uint8Array([a, b])); const cs = Array.from(s); if (cs.length === 1) set.add(cs[0]); } catch (_) { /* unmapped */ }
  }
  return set;
}

// Same acceptance rules as ferrous-opencc-compiler: skip blank and # lines, require
// exactly one tab, split values on single spaces and reject empty values; the last
// duplicate key wins. Only the first value is ever used for conversion.
function readDict(name) {
  const text = fs.readFileSync(path.join(dictDir, name + '.txt'), 'utf8');
  const map = new Map();
  for (let line of text.split('\n')) {
    if (line.endsWith('\r')) line = line.slice(0, -1);
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const parts = line.split('\t');
    if (parts.length !== 2) continue;
    const [key, rest] = parts;
    const values = rest.split(' ');
    if (!key || !values.length || values.some((v) => !v)) continue;
    map.set(key, values[0]);
  }
  return map;
}

function serialize(map) {
  const keys = [...map.keys()].sort();
  return keys.map((k) => k + '\t' + map.get(k)).join('\n');
}

const hanzi = gb2312Hanzi();
if (hanzi.size !== 6763) throw new Error('unexpected GB2312 hanzi count ' + hanzi.size);
const st = readDict('STCharacters');
const phrasesAll = readDict('STPhrases');
// Phrase keys made of anything other than GB2312 hanzi can never match: the converter
// only feeds font hanzi (and private-use placeholders) into the first conversion stage.
const phrases = new Map([...phrasesAll].filter(([k]) => Array.from(k).every((c) => hanzi.has(c))));
const tw = readDict('TWVariants');
const hk = readDict('HKVariants');

const header = (what) => `/*
 * ${what}
 * Generated by third_party/zh_js/generate_data.js. Do not edit by hand.
 */
`;
const opencc = header('OpenCC dictionaries (Apache-2.0) for src/zh_converter.js.\n' +
  ' * Source: Open Chinese Convert, https://github.com/BYVoid/OpenCC\n' +
  ' * Copyright (c) Carbo Kuo (BYVoid) and OpenCC contributors. Licensed under the\n' +
  ' * Apache License, Version 2.0; see third_party/zh_js/LICENSE-OpenCC-Apache-2.0.txt.\n' +
  ' * Modification: STPhrases is limited to keys made only of GB2312 hanzi; all\n' +
  ' * entries are reduced to their first value; files are re-serialised as\n' +
  ' * "key<TAB>value" lines') +
  `(function (root) {
'use strict';
const D = root.ParaLabZhData = root.ParaLabZhData || {};
D.opencc = {
  STCharacters: ${JSON.stringify(serialize(st))},
  STPhrases: ${JSON.stringify(serialize(phrases))},
  TWVariants: ${JSON.stringify(serialize(tw))},
  HKVariants: ${JSON.stringify(serialize(hk))},
};
if (typeof module !== 'undefined') module.exports = D;
})(typeof window !== 'undefined' ? window : globalThis);
`;
fs.writeFileSync(path.join(out, 'opencc_data.js'), opencc);

function glyphFile(id, label, license, files) {
  const packs = {};
  for (const [key, file] of Object.entries(files)) {
    if (/zpix/i.test(file)) throw new Error('Zpix is not permissively licensed and must not be packed');
    const bytes = fs.readFileSync(path.join(glyphDir, file));
    const magic = bytes.subarray(0, 4).toString('latin1');
    if (magic !== 'FPG1' && magic !== 'FPG2') throw new Error(file + ' is not a glyph pack');
    packs[key] = bytes.toString('base64');
  }
  const src = header(label + ' glyph packs for src/zh_converter.js.\n' +
    ' * Bitmaps rasterised from the font by the MIT-licensed tamagotchi-paradise-zh-patcher\n' +
    ' * glyphpack-gen tool. Font software licensed under the SIL Open Font License 1.1;\n' +
    ' * see third_party/zh_js/' + license + '. Reserved Font Names are not used for\n' +
    ' * this derived data') +
    `(function (root) {
'use strict';
const D = root.ParaLabZhData = root.ParaLabZhData || {};
D.glyphs = D.glyphs || {};
${Object.entries(packs).map(([k, v]) => `D.glyphs[${JSON.stringify(k)}] = ${JSON.stringify(v)};`).join('\n')}
if (typeof module !== 'undefined') module.exports = D;
})(typeof window !== 'undefined' ? window : globalThis);
`;
  fs.writeFileSync(path.join(out, id + '.js'), src);
}

glyphFile('glyphs_cubic11', 'Cubic 11 (https://github.com/ACh-K/Cubic-11)', 'OFL-Cubic11.txt',
  { cubic11: 'cubic11.glyphs', latin_cubic11: 'latin_cubic11.glyphs' });
glyphFile('glyphs_fusion12', 'Fusion Pixel Font 12px zh_hk (https://github.com/TakWolf/fusion-pixel-font)', 'OFL-FusionPixel.txt',
  { fusion12: 'fusion12_zh_hk.glyphs', latin_fusion12: 'latin_fusion12.glyphs' });

console.log('STCharacters', st.size, 'STPhrases', phrases.size, '/', phrasesAll.size, 'TW', tw.size, 'HK', hk.size);
for (const f of ['opencc_data.js', 'glyphs_cubic11.js', 'glyphs_fusion12.js'])
  console.log(f, fs.statSync(path.join(out, f)).size);
